/** AgriNova introduction and entry screen. */
const copy={en:{title:'AgriNova',body:'Turn Earth observations and your own field records into clearer farming decisions. Explore local weather, water demand, soil conditions, resilient crop rotations and profit scenarios for the exact land you choose.',enter:'Enter AgriNova',replay:'Replay introduction',replayBody:'See the AgriNova introduction again.'},fr:{title:'AgriNova',body:'Transformez les observations de la Terre et vos propres relevés de terrain en décisions agricoles plus claires. Explorez la météo locale, les besoins en eau, l’état du sol, les rotations résilientes et les scénarios de bénéfices pour la terre choisie.',enter:'Entrer dans AgriNova',replay:'Revoir l’introduction',replayBody:'Revoir l’introduction de AgriNova.'},ar:{title:'فيلد شيفت',body:'حوّل رصد الأرض وسجلات حقلك إلى قرارات زراعية أوضح. استكشف الطقس المحلي واحتياجات المياه وحالة التربة وتناوب المحاصيل المرن وسيناريوهات الربح للأرض التي تختارها.',enter:'دخول فيلد شيفت',replay:'إعادة المقدمة',replayBody:'شاهد مقدمة فيلد شيفت مرة أخرى.'}};

export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en',zoomTimer,revealTimer,hideTimer;
  const overlay=document.createElement('section');overlay.className='fieldshift-intro earth-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','AgriNova introduction');
  overlay.innerHTML='<div class="earth-landscape" aria-hidden="true"></div><div class="earth-intro-copy"><img class="earth-intro-logo" src="assets/logo-new.png" alt="AgriNova logo"><h1></h1><p></p><button type="button" class="earth-intro-enter"></button></div>';document.body.append(overlay);
  const enter=overlay.querySelector('.earth-intro-enter');
  const panel=document.querySelector('.settings-panel'),row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const apply=()=>{const words=copy[current];overlay.querySelector('h1').textContent=words.title;overlay.querySelector('p').textContent=words.body;enter.textContent=words.enter;row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};
  const clear=()=>{clearTimeout(zoomTimer);clearTimeout(revealTimer);clearTimeout(hideTimer);};
  const close=()=>{clear();sessionStorage.setItem('fieldshift.intro.skip-auto','1');overlay.classList.add('leaving');document.body.classList.remove('intro-open','intro-pending');hideTimer=setTimeout(()=>overlay.hidden=true,380);document.querySelector('.topbar-field')?.focus();window.dispatchEvent(new CustomEvent('fieldshift:intro:closed'));};
  const open=()=>{clear();overlay.hidden=false;overlay.classList.remove('leaving','zooming','revealed');document.body.classList.add('intro-open','intro-pending');enter.disabled=false;void overlay.offsetWidth;overlay.classList.add('revealed');enter.focus();};
  enter.onclick=close;
  row.querySelector('button').onclick=open;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();});apply();if(!sessionStorage.getItem('fieldshift.intro.skip-auto'))requestAnimationFrame(open);else {overlay.hidden=true;document.body.classList.remove('intro-pending');}return{open};
}
